kubejs:ender_golem_line.body:
const player = event.player
    const level = event.level
    const chestCavity = player.getChestCavityInstance()
    const strengthScore = chestCavity.getOrganScoreOrDefault('chestcavity:strength', 0)
    let playerPos = player.position()
    let entityList = GetLivingWithinRadiusVec3d(level, playerPos, 32, (level, entity) => {
        return !entity.equals(player)
    })
    entityList.forEach(entity => {
        let entityPos = entity.position()
        let diff = playerPos.subtract(entityPos)
        entity.setDeltaMovement(Vec3dNormalize(diff).scale(strengthScore))
        for (let i = 0; i < 3; i++) {
            level.spawnParticles($ParticleTypes.PORTAL, true, entityPos.x() + Math.random(), entityPos.y() + Math.random(), entityPos.z() + Math.random(), 0.2, 0.3, 0.2, 5, 0)
        }
    })
    player.addItemCooldown(organItem, 20 * 3)

kubejs:endermite_gland.body:
const entity = event.entity
    const level = event.level
    /**@type {Internal.PathfinderMob} */
    let entities = GetLivingWithinRadiusVec3d(level, entity.position(), 16, (pLevel, pEntity) => {
        if (!(pEntity instanceof $PathfinderMob)) return false
        if (!pEntity.isMonster()) return false
        if (pEntity.getTarget() && pEntity.getTarget().equals(entity)) return false
        return true
    })
    entities.forEach((pEntity) => {
        pEntity.setTarget(entity)
    })

kubejs:basin.body:
const player = event.entity
    const chestCavity = player.chestCavityInstance
    const ccInv = chestCavity.inventory
    const invTypeData = chestCavity.getInventoryTypeData()
    let aboveSlots = GetDirectionRelativeSlotByParam(invTypeData, organIndex, [[0, -1]])
    if (aboveSlots.length == 0) return

    let aboveSlotDef = aboveSlots[0]
    let aboveSlotIndex = aboveSlotDef.getId()
    let aboveItem = ccInv.getStackInSlot(aboveSlotIndex)

    if (aboveItem.isEmpty()) return

    let itemCopy = aboveItem.copy()
    let insertedCount = AddItemIntoBundle(organItem, itemCopy, 64, pStack => pStack.getMaxStackSize() / 64)
    if (insertedCount <= 0) return
    aboveItem.shrink(insertedCount)

kubejs:belt_connecter.body:
const player = event.entity
    const chestCavity = player.chestCavityInstance
    if (slotType == AutomationSlot) {
        SetCustomDataMap(chestCavity, 'beltEnabled', 1)
        let organEffect = new OragnEffectModel(organItem).setPriority(organIndex).setCustomText('ON')
        SetOrganEffect(chestCavity, organEffect)
    }

const player = event.entity
    const chestCavity = player.chestCavityInstance
    const query = chestCavity.getOrganQueryIndex()
    if (!query.hasItem('kubejs:belt_connecter', true, AutomationSlot)
        && !query.hasItem('kubejs:mechanized_belt', true, MachinaryLubricant)) {
        RemoveCustomDataMap(chestCavity, 'beltEnabled')
    }
    RemoveOrganEffect(chestCavity, 'kubejs:belt_connecter')

const player = event.player
    const chestCavity = player.chestCavityInstance
    if (slotType == AutomationSlot) {
        const beltEffect = GetFactoryBeltEffect(chestCavity)
        const mode = beltEffect > 0 ? 0 : 1
        SetCustomDataMap(chestCavity, 'beltEnabled', mode)
        let organEffect = new OragnEffectModel(organItem).setPriority(organIndex).setCustomText(beltEffect > 0 ? 'OFF' : 'ON')
        SetOrganEffect(chestCavity, organEffect)
        player.addItemCooldown(organItem, 20 * 2)
    }

kubejs:brass_funnel.body:
const player = event.entity

    const chestCavity = player.chestCavityInstance

    const inventory = chestCavity.inventory
    const invTypeData = chestCavity.getInventoryTypeData()
    let belowSlots = GetDirectionRelativeSlotByParam(invTypeData, organIndex, [[0, 1]])
    if (belowSlots.length == 0) return

    let belowSlotDef = belowSlots[0]
    let belowSlotIndex = belowSlotDef.getId()
    let belowItem = inventory.getStackInSlot(belowSlotIndex)

    // 如果下方没有物品，不执行
    if (belowItem.isEmpty()) return
    if (belowItem.getItem() instanceof $BundleItem) return
    let contents = GetBundleContents(organItem)
    let filterItem = contents[0]
    if (filterItem != null) {
        if (filterItem.getId() != belowItem.getId()) return
    }
    let rightSlots = GetDirectionRelativeSlotByParam(invTypeData, organIndex, [[1, 0]])
    if (rightSlots.length == 0) return
    let rightSlotDef = rightSlots[0]
    let rightSlotIndex = rightSlotDef.getId()
    let rightItem = inventory.getStackInSlot(rightSlotIndex)
    if (rightItem.isEmpty() || rightItem.getCount() != 1) return
    // 仅通用储物器官可接收物流；过滤器、催化物槽和普通物品不能成为伪容器。
    let capacity
    switch (String(rightItem.getId())) {
        case 'kubejs:basin': capacity = 128; break
        case 'kubejs:deployer':
        case 'kubejs:crushing_wheel': capacity = 64; break
        default: return
    }
    let available = capacity - GetBundleCountentWeight(rightItem, pStack => 1)
    if (available <= 0) return
    let itemCopy = belowItem.copy()
    itemCopy.setCount(Math.min(itemCopy.getCount(), available))
    let insertedCount = AddItemIntoBundle(rightItem, itemCopy, 64, pStack => pStack.getMaxStackSize() / 64)
    if (insertedCount <= 0) return
    belowItem.shrink(insertedCount)

kubejs:crushing_wheel.body:
const player = event.entity
    const level = player.level
    const chestCavity = player.chestCavityInstance
    if (slotType == FastWorkingSlot) return
    ChangeItemDamage(organItem, 1)
    let stressValue = chestCavity.getOrganScore('kubejs:stress')
    if (stressValue < 0) return
    let groups = GetBundleIngredientGroups(organItem)
    if (groups.length != 1) {
        return
    }

    let curItem = groups[0].item
    if (curItem.isEmpty()) return
    let outputItemList = null
    let recipe = crushingWheelOrganRecipe(curItem)
    if (recipe == null) {
        outputItemList = GetProcessingRecipeResults(level, curItem, [$CreateRecipesType.CRUSHING, $CreateRecipesType.MILLING], chestCavity, organIndex)
    } else {
        outputItemList = recipe
    }
    if (outputItemList.length <= 0) return
    let firstOutput = outputItemList[0]
    let otherOutputs = []
    for (let i = 1; i < outputItemList.length; i++) {
        otherOutputs.push(outputItemList[i])
    }

    const beltEffect = GetFactoryBeltEffect(chestCavity)
    const ccInv = chestCavity.inventory
    const invTypeData = chestCavity.getInventoryTypeData()
    if (beltEffect == 1) {
        if (groups[0].count == 1 && organItem.getNbt().contains('otherbeltmode')) {
            let belowSlot = GetDirectionRelativeSlotByParam(invTypeData, organIndex, [[0, 1]])
            if (belowSlot.length == 0) return
            let belowItem = ccInv.getStackInSlot(belowSlot[0].getId())
            if (!belowItem.isEmpty()) return
            if (!ConsumeBundleIngredients(organItem, groups, [1])) return
            ChangeItemDamage(organItem, -5)
            let targetIndex = belowSlot[0].getId()
            let targetSlotType = chestCavity.inventoryTypeData.getSlotType(targetIndex)
            SetChestCavityOrgan(customData, chestCavity, firstOutput.copy(), targetIndex, targetSlotType, true)
            if (otherOutputs.length > 0) {
                SpawnLootAtLocation(level, player.blockPosition(), otherOutputs)
            }
        } else {
            let outputSlot = GetDirectionRelativeSlotByParam(invTypeData, organIndex, [[1, 1]])
            if (outputSlot.length == 0) return
            let outputItem = ccInv.getStackInSlot(outputSlot[0].getId())
            if (!CanMergeItemStacks(outputItem, firstOutput, ccInv.getMaxStackSize())) return

            if (!ConsumeBundleIngredients(organItem, groups, [1])) return
            ChangeItemDamage(organItem, -5)
            SetChestCavityOutput(customData, chestCavity, firstOutput, outputSlot[0].getId(), false)

            if (otherOutputs.length > 0) {
                SpawnLootAtLocation(level, player.blockPosition(), otherOutputs)
            }
        }
    } else {
        if (!ConsumeBundleIngredients(organItem, groups, [1])) return
        ChangeItemDamage(organItem, -5)
        SpawnLootAtLocation(level, player.blockPosition(), outputItemList)
    }

const player = event.entity
    const level = player.level
    const chestCavity = player.chestCavityInstance
    let stressValue = chestCavity.getOrganScore('kubejs:stress')
    if (stressValue < 0) return
    if (slotType == FastWorkingSlot) {
        let groups = GetBundleIngredientGroups(organItem)
        if (groups.length != 1) {
            return
        }
        let curItem = groups[0].item
        if (curItem.isEmpty()) return
        let itemCount = groups[0].count
        let testItem = curItem.copy()
        testItem.setCount(1)
        let recipe = crushingWheelOrganRecipe(testItem)
        let outputItemList = null
        if (recipe == null) {
            outputItemList = GetProcessingRecipeResults(level, testItem, [$CreateRecipesType.CRUSHING, $CreateRecipesType.MILLING], chestCavity, organIndex)
        } else {
            outputItemList = recipe
        }
        if (outputItemList.length <= 0) return
        let fastOutputs = ScaleItemOutputs(outputItemList, itemCount)
        if (!ConsumeBundleIngredients(organItem, groups, [itemCount])) return
        SpawnLootAtLocation(level, player.blockPosition(), fastOutputs)
    }

const player = event.entity
    if (!player.isPlayer()) return
    if (organItem.getDamageValue() == 100) {
        let staleAttribute = player.getAttribute('minecraft:generic.attack_damage')
        if (staleAttribute) staleAttribute.removeModifier(crushingWheelUUID)
        return
    }
    const chestCavity = player.chestCavityInstance
    const attributeInstance = player.getAttribute('minecraft:generic.attack_damage')
    if (!attributeInstance) return
    let stressValue = chestCavity.getOrganScore('kubejs:stress')
    if (stressValue < 0) {
        attributeInstance.removeModifier(crushingWheelUUID)
        return
    }
    let remaining = organItem.getMaxDamage() - organItem.getDamageValue()
    let mainhand = player.mainHandItem
    let isHoldingWrench = false
    if (!mainhand.isEmpty()) {
        if (mainhand.hasTag('forge:tools/wrench')) {
            isHoldingWrench = true
        }
    }
    if (isHoldingWrench) {
        attributeInstance.removeModifier(crushingWheelUUID)
        let attributeModifier = new $AttributeModifier(
            crushingWheelUUID,
            'CrushingWheel',
            (stressValue * remaining) / 2,
            $Operation.ADDITION
        )
        attributeInstance.addPermanentModifier(attributeModifier)
    } else {
        attributeInstance.removeModifier(crushingWheelUUID)
    }

kubejs:deployer.body:
const player = event.entity
    const level = player.level
    const chestCavity = player.chestCavityInstance
    if (slotType == FastWorkingSlot) return
    const ccInv = chestCavity.inventory
    const invTypeData = chestCavity.getInventoryTypeData()
    ChangeItemDamage(organItem, 1)
    let stressValue = chestCavity.getOrganScore('kubejs:stress')
    if (stressValue < 0) return
    let belowSlot = GetDirectionRelativeSlotByParam(invTypeData, organIndex, [[0, 1]])
    if (belowSlot.length == 0) return
    let curItem = ccInv.getStackInSlot(belowSlot[0].getId())
    if (curItem.isEmpty()) return
    let bundleGroups = GetBundleIngredientGroups(organItem)
    if (bundleGroups.length == 0) return
    let bundleItem = bundleGroups[0].item
    let outputItem = deployerOrganRecipe(curItem, bundleItem)
    if (outputItem == null) return
    const beltEffect = GetFactoryBeltEffect(chestCavity)
    if (beltEffect == 1) {
        if (curItem.getCount() == 1 && organItem.getNbt().contains('otherbeltmode')) {
            if (!bundleItem.hasTag('create:sandpaper') && !ConsumeBundleIngredients(organItem, [bundleGroups[0]], [1])) return
            curItem.shrink(1)
            ChangeItemDamage(organItem, -5)
            let targetIndex = belowSlot[0].getId()
            let targetSlotType = chestCavity.inventoryTypeData.getSlotType(targetIndex)
            SetChestCavityOrgan(customData, chestCavity, outputItem.copy(), targetIndex, targetSlotType, true)
        } else {
            let outputSlot = GetDirectionRelativeSlotByParam(invTypeData, organIndex, [[1, 1]])
            if (outputSlot.length == 0) return
            let existingItem = ccInv.getStackInSlot(outputSlot[0].getId())
            if (!CanMergeItemStacks(existingItem, outputItem, ccInv.getMaxStackSize())) return

            if (!bundleItem.hasTag('create:sandpaper') && !ConsumeBundleIngredients(organItem, [bundleGroups[0]], [1])) return
            curItem.shrink(1)
            ChangeItemDamage(organItem, -5)
            SetChestCavityOutput(
                customData,
                chestCavity,
                outputItem,
                outputSlot[0].getId(),
                !chestCavity.getOrganQueryIndex().hasItem('kubejs:factory_heart', true, FactoryCoreSlot)
            )
        }
    } else {
        if (!bundleItem.hasTag('create:sandpaper') && !ConsumeBundleIngredients(organItem, [bundleGroups[0]], [1])) return
        curItem.shrink(1)
        ChangeItemDamage(organItem, -5)
        SpawnLootAtLocation(level, player.blockPosition(), [outputItem])
    }

const player = event.entity
    const level = player.level
    const chestCavity = player.chestCavityInstance
    const ccInv = chestCavity.inventory
    const invTypeData = chestCavity.getInventoryTypeData()
    let stressValue = chestCavity.getOrganScore('kubejs:stress')
    if (stressValue < 0) return
    if (slotType == FastWorkingSlot) {
        let belowSlot = GetDirectionRelativeSlotByParam(invTypeData, organIndex, [[0, 1]])
        if (belowSlot.length == 0) return
        let curItem = ccInv.getStackInSlot(belowSlot[0].getId())
        if (curItem.isEmpty()) return
        let itemCount = curItem.getCount()
        let bundleGroups = GetBundleIngredientGroups(organItem)
        if (bundleGroups.length == 0) return
        let bundleItem = bundleGroups[0].item
        let bundleCount = bundleGroups[0].count
        let outputItem = deployerOrganRecipe(curItem, bundleItem)
        if (outputItem == null) return
        let consumesMaterial = !bundleItem.hasTag('create:sandpaper')
        let count = consumesMaterial ? Math.min(itemCount, bundleCount) : itemCount
        if (consumesMaterial && !ConsumeBundleIngredients(organItem, [bundleGroups[0]], [count])) return
        outputItem.setCount(count)
        curItem.shrink(count)
        SpawnLootAtLocation(level, player.blockPosition(), [outputItem])
    }

kubejs:encased_fan.body:
const player = event.entity
    const level = player.level
    const registryAccess = level.registryAccess()
    const chestCavity = player.chestCavityInstance
    if (slotType == FastWorkingSlot) return
    const ccInv = chestCavity.inventory
    const invTypeData = chestCavity.getInventoryTypeData()
    ChangeItemDamage(organItem, 1)
    let stressValue = chestCavity.getOrganScore('kubejs:stress')
    if (stressValue < 0) return
    let belowSlot = GetDirectionRelativeSlotByParam(invTypeData, organIndex, [[0, 1]])
    if (belowSlot.length == 0) return
    let curItem = ccInv.getStackInSlot(belowSlot[0].getId())
    if (curItem.isEmpty()) return
    let recipe = encasedFanOrganRecipe(curItem)
    let outputItem = null
    if (recipe == null) {
        let smeltingRecipe = GetSmeltingRecipe(level, curItem, chestCavity, organIndex)
        if (!smeltingRecipe) {
            if (curItem.getId() == 'kubejs:throat_fabritem' && curItem.hasNBT()) {
                if (!curItem.getNbt().contains('greedyThroatUUID')) return
                outputItem = Item.of('kubejs:throat_fabritem')
            } else return
        } else {
            outputItem = smeltingRecipe.getResultItem(registryAccess).copy()
            if (outputItem.isEmpty()) return
        }
    } else {
        outputItem = recipe
    }
    const beltEffect = GetFactoryBeltEffect(chestCavity)
    if (beltEffect == 1) {
        if (curItem.getCount() == 1 && organItem.getNbt().contains('otherbeltmode')) {
            curItem.shrink(1)
            ChangeItemDamage(organItem, -5)
            let targetIndex = belowSlot[0].getId()
            let targetSlotType = chestCavity.inventoryTypeData.getSlotType(targetIndex)
            SetChestCavityOrgan(customData, chestCavity, outputItem.copy(), targetIndex, targetSlotType, true)
        } else {
            let outputSlot = GetDirectionRelativeSlotByParam(invTypeData, organIndex, [[1, 1]])
            if (outputSlot.length == 0) return
            let existingItem = ccInv.getStackInSlot(outputSlot[0].getId())
            if (!CanMergeItemStacks(existingItem, outputItem, ccInv.getMaxStackSize())) return

            curItem.shrink(1)
            ChangeItemDamage(organItem, -5)
            SetChestCavityOutput(
                customData,
                chestCavity,
                outputItem,
                outputSlot[0].getId(),
                !chestCavity.getOrganQueryIndex().hasItem('kubejs:factory_heart', true, FactoryCoreSlot)
            )
            if (slotType == DigestSlot) encasedFanResetGreedyThroatCooldown(player, chestCavity)
        }
    } else {
        curItem.shrink(1)
        ChangeItemDamage(organItem, -5)
        SpawnLootAtLocation(level, player.blockPosition(), [outputItem])
        if (slotType == DigestSlot) encasedFanResetGreedyThroatCooldown(player, chestCavity)
    }

const player = event.entity
    const level = player.level
    const registryAccess = level.registryAccess()
    const chestCavity = player.chestCavityInstance
    const ccInv = chestCavity.inventory
    const invTypeData = chestCavity.getInventoryTypeData()
    let stressValue = chestCavity.getOrganScore('kubejs:stress')
    if (stressValue < 0) return
    if (slotType == FastWorkingSlot) {
        let belowSlot = GetDirectionRelativeSlotByParam(invTypeData, organIndex, [[0, 1]])
        if (belowSlot.length == 0) return
        let curItem = ccInv.getStackInSlot(belowSlot[0].getId())
        if (curItem.isEmpty()) return
        let itemCount = curItem.getCount()
        let recipe = encasedFanOrganRecipe(curItem)
        let outputItem = null
        if (recipe == null) {
            let smeltingRecipe = GetSmeltingRecipe(level, curItem, chestCavity, organIndex)
            if (!smeltingRecipe) return
            outputItem = smeltingRecipe.getResultItem(registryAccess).copy()
            if (outputItem.isEmpty()) return
        } else {
            outputItem = recipe
        }
        outputItem.setCount(itemCount)

        curItem.shrink(itemCount)
        SpawnLootAtLocation(level, player.blockPosition(), [outputItem])
    }

const player = event.entity
    if (!player.isPlayer()) return
    if (slotType == DigestSlot) {
        ChangeItemDamage(organItem, -5)
    }
    if (organItem.getDamageValue() == 100) {
        let staleAttribute = player.getAttribute('ars_nouveau:ars_nouveau.perk.mana_regen')
        if (staleAttribute) staleAttribute.removeModifier(encasedFanUUID)
        return
    }
    const level = player.level
    const chestCavity = event.chestCavity
    let stressValue = chestCavity.getOrganScore('kubejs:stress')
    if (stressValue < 0) {
        let staleAttribute = player.getAttribute('ars_nouveau:ars_nouveau.perk.mana_regen')
        if (staleAttribute) staleAttribute.removeModifier(encasedFanUUID)
        return
    }
    let remaining = organItem.getMaxDamage() - organItem.getDamageValue()
    const fanEffect = encasedFanMode(organItem)
    if (fanEffect != 3) {
        let staleAttribute = player.getAttribute('ars_nouveau:ars_nouveau.perk.mana_regen')
        if (staleAttribute) staleAttribute.removeModifier(encasedFanUUID)
    }
    if (fanEffect == 1) {
        let fireTick = player.getRemainingFireTicks()
        if (remaining != 0) {
            fireTick = fireTick + (stressValue * remaining) / 2
            player.setRemainingFireTicks(fireTick)
        } else {
            player.setRemainingFireTicks(0)
        }
    } else if (fanEffect == 2) {
        if (stressValue < 5) return
        if (remaining < 90) return
        if (player.age % 200 != 0) return
        RecoverPlayerHungerAndSaturation(player, 20)
    } else if (fanEffect == 3) {
        const attributeInstance = event.entity.getAttribute('ars_nouveau:ars_nouveau.perk.mana_regen')
        if (!attributeInstance) return
        let stressValue = chestCavity.getOrganScore('kubejs:stress')
        let remaining = organItem.getMaxDamage() - organItem.getDamageValue()
        attributeInstance.removeModifier(encasedFanUUID)
        let attributeModifier = new $AttributeModifier(encasedFanUUID, 'Encasedfan', (stressValue * remaining) / 100, $Operation.ADDITION)
        attributeInstance.addPermanentModifier(attributeModifier)
    } else if (fanEffect == 4) {
        if (stressValue < 2) return
        if (!player.isCrouching()) return
        const blockPos = event.entity.blockPosition()
        const radius = Math.min(16, Math.floor(stressValue / 2))
        for (let dx = -radius; dx <= radius; dx++) {
            for (let dy = -1; dy <= 1; dy++) {
                for (let dz = -radius; dz <= radius; dz++) {
                    TryBonemeal(level, blockPos.offset(dx, dy, dz), player, 'minecraft:happy_villager', true)
                }
            }
        }
    }

ClearCachedNativeRecipe(event.entity.chestCavityInstance, organIndex)
    const { entity } = event
    const attributeInstance = entity.getAttribute('ars_nouveau:ars_nouveau.perk.mana_regen')
    if (attributeInstance) {
        attributeInstance.removeModifier(encasedFanUUID)
    }

kubejs:factory_heart.body:
const player = event.entity
    if (slotType != FactoryCoreSlot) return
    const chestCavity = player.chestCavityInstance
    const inventory = chestCavity.inventory
    let finalIndex = chestCavity.inventory.find('kubejs:final_fabritem')
    if (finalIndex == 18) {
        let firstItem = inventory.getStackInSlot(10)
        if (!firstItem.isEmpty()) return
        let finalItem = inventory.getStackInSlot(finalIndex)
        let newItem = finalItem.copy()
        finalItem.shrink(1)
        let targetIndex = 10
        let targetSlotType = chestCavity.inventoryTypeData.getSlotType(targetIndex)
        SetChestCavityOrgan(customData, chestCavity, newItem, targetIndex, targetSlotType, false)
    }

kubejs:genius.body:
const chestCavity = event.chestCavity
    const entity = event.entity
    let stressValue = chestCavity.getOrganScore('kubejs:stress')
    const effects = entity.getActiveEffects()
    const effectCount = effects.size()
    stressValue = stressValue + effectCount
    chestCavity.setOrganScore('kubejs:stress', stressValue)

kubejs:item_drain.body:
const player = event.entity
    const level = player.level
    const chestCavity = player.chestCavityInstance
    const ccInv = chestCavity.inventory
    const invTypeData = chestCavity.getInventoryTypeData()
    ChangeItemDamage(organItem, 1)
    let stressValue = chestCavity.getOrganScore('kubejs:stress')
    if (stressValue < 0) return
    let aboveSlot = GetDirectionRelativeSlotByParam(invTypeData, organIndex, [[0, -1]])
    if (aboveSlot.length == 0) return
    let aboveSlotDef = aboveSlot[0]
    let aboveSlotIndex = aboveSlotDef.getId()
    let inputItem = ccInv.getStackInSlot(aboveSlotIndex)
    if (inputItem.isEmpty()) return
    let outputItem = null
    let fluidToAdd = null
    let drainRecipe = itemDrainOrganRecipe(inputItem)
    let itemType = inputItem.getItem()
    if (drainRecipe != null) {
        outputItem = drainRecipe.output
        fluidToAdd = drainRecipe.fluidToAdd
    } else if (itemType instanceof $BucketItem) {
        if (itemType instanceof $MobBucketItem || itemType instanceof $sulfurcubebucketitem) return
        let fluid = inputItem.getId().replace('_bucket', '')
        outputItem = Item.of('minecraft:bucket')
        fluidToAdd = Fluid.of(fluid, 1000)
    } else return
    const beltEffect = GetFactoryBeltEffect(chestCavity)
    let bundleSource = organItem
    let targetIndex = -1
    let replaceInput = false
    if (beltEffect == 1) {
        const query = chestCavity.getOrganQueryIndex()
        const spoutIndex = query.hasItem('create:mechanical_pump', false, null)
            ? query.findItem('kubejs:spout', false, null) : -1
        if (spoutIndex >= 0) {
            let spoutItem = ccInv.getStackInSlot(spoutIndex)
            if (!spoutItem.isEmpty() && spoutItem.getId() == 'kubejs:spout') bundleSource = spoutItem
        }
        if (inputItem.getCount() == 1 && organItem.hasNBT() && organItem.getNbt().contains('otherbeltmode')) {
            targetIndex = aboveSlotIndex
            replaceInput = true
        } else {
            let outputSlot = GetDirectionRelativeSlotByParam(invTypeData, organIndex, [[1, -1]])
            if (outputSlot.length == 0) return
            targetIndex = outputSlot[0].getId()
            let existingItem = ccInv.getStackInSlot(targetIndex)
            if (!CanMergeItemStacks(existingItem, outputItem, ccInv.getMaxStackSize())) return
        }
    }
    let contents = GetBundleContents(bundleSource)
    let bundleItem = contents[0]
    if (bundleItem == null) return
    // Fill a detached canister and commit only after the full amount is accepted.
    let tankHandler = GetItemFluidHandler(bundleItem.copy())
    if (!tankHandler) return
    let amount = fluidToAdd.getAmount()
