    const chestCavity = event.chestCavity
    let magicData = entity.getMagicData()
    let curMana = magicData.getMana()
    if (curMana <= 50) return
    let damageValue = curMana / 50 + organItem.getDamageValue()
    let maxDamageValue = organItem.getMaxDamage()
    if (damageValue >= maxDamageValue) {
        SetChestCavityOrgan(customData, chestCavity, Item.of('kubejs:source_focus_crystal'), organIndex, slotType, true)
    } else {
        organItem.setDamageValue(damageValue)
    }
    magicData.setMana(0)

kubejs:heal_star_gem.body:
const resolveEffect = event.resolveEffect
    if (resolveEffect.getRegistryName() != 'ars_nouveau:glyph_heal') return
    /**@type {Internal.EntityHitResult} */
    const hitResult = event.rayTraceResult
    const spellStats = event.spellStats
    if (!(hitResult instanceof $EntityHitResult)) return
    /**@type {Internal.LivingEntity } */
    let entity = hitResult.getEntity()
    let duration = Math.max(60, 20 * (spellStats.getAmpMultiplier() + 1) * 3)
